import java.security.SecureRandom;

public class PasswordGenerator {

    private static final String ALPHA = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String DIGIT = "0123456789";
    private static final String SPECIAL = "!@#$%^&*()-_=+[]{}|;:',.<>/?";
    private static final String ALL_CHARS = ALPHA + DIGIT + SPECIAL;

    private static final SecureRandom RANDOM;

    static {
        SecureRandom tempRandom;
        try {
            tempRandom = SecureRandom.getInstanceStrong();
        } catch (NoSuchAlgorithmException e) {
            tempRandom = new SecureRandom();
        }
        RANDOM = tempRandom;
    }

    /**
     * Generates a secure random password of specified length, respecting restrictions on the end character.
     *
     * @param length                  the length of the password to generate
     * @param mustNotEndWithAlpha     if true, the last character cannot be alphabetic
     * @param mustNotEndWithDigit     if true, the last character cannot be a digit
     * @param mustNotEndWithNonAlpha  if true, the last character cannot be a special (non-alphanumeric) character
     * @return the generated password as a String
     * @throws IllegalArgumentException if the length is invalid or restrictions exclude all possible end characters
     */
    public static String generatePassword(int length, 
                                          boolean mustNotEndWithAlpha, 
                                          boolean mustNotEndWithDigit, 
                                          boolean mustNotEndWithNonAlpha) {
        if (length <= 0) {
            throw new IllegalArgumentException("Password length must be greater than zero.");
        }

        StringBuilder password = new StringBuilder(length);

        for (int i = 0; i < length - 1; i++) {
            password.append(ALL_CHARS.charAt(RANDOM.nextInt(ALL_CHARS.length())));
        }

        StringBuilder lastCharPool = new StringBuilder();
        if (!mustNotEndWithAlpha) {
            lastCharPool.append(ALPHA);
        }
        if (!mustNotEndWithDigit) {
            lastCharPool.append(DIGIT);
        }
        if (!mustNotEndWithNonAlpha) {
            lastCharPool.append(SPECIAL);
        }

        if (lastCharPool.length() == 0) {
            throw new IllegalArgumentException("Invalid restrictions: all character types are restricted from the end of the password.");
        }

        char lastChar = lastCharPool.charAt(RANDOM.nextInt(lastCharPool.length()));
        password.append(lastChar);

        return password.toString();
    }
}
