     * Randomly performs heartbeat and clear primary operations on the given node
     * for a total number of iterations equal to the sum of expected operations,
     * and logs the difference between the actual and expected counts.
     *
     * @param node                   the node on which to perform operations, must not be null
     * @param expectedHeartbeats     the expected number of heartbeat operations, must be non-negative
     * @param expectedClearPrimaries the expected number of clear primary operations, must be non-negative
     * @throws IllegalArgumentException if the node is null, expected counts are negative, or total count overflows
     */
    public void performRandomOperations(Node node, int expectedHeartbeats, int expectedClearPrimaries) {
        if (node == null) {
            throw new IllegalArgumentException("Node must not be null");
        }
        if (expectedHeartbeats < 0 || expectedClearPrimaries < 0) {
            throw new IllegalArgumentException("Expected operation counts must be non-negative");
