    static class TraversalThread extends Thread {
        private final Graph graph;
        private final int startVertex;
        private final Set<Integer> visited;
        private final AtomicInteger completedThreads;

        public TraversalThread(Graph graph, int startVertex, Set<Integer> visited, AtomicInteger completedThreads) {
            this.graph = graph;
            this.startVertex = startVertex;
            this.visited = visited;
            this.completedThreads = completedThreads;
        }

        @Override
        public void run() {
            try {
                bfs(startVertex);
            } finally {
                completedThreads.incrementAndGet();
            }
        }

        private void bfs(int start) {
            Queue<Integer> queue = new LinkedList<>();
            if (visited.add(start)) {
                queue.add(start);
            }

            while (!queue.isEmpty()) {
                if (Thread.currentThread().isInterrupted()) {
                    break;
                }
                Integer current = queue.poll();
                if (current == null) {
                    continue;
                }

                for (Integer neighbor : graph.getNeighbors(current)) {
                    if (visited.add(neighbor)) {
                        queue.add(neighbor);
                    }
                }
            }
        }
    }
