import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.SocketChannel;
import java.util.Iterator;
import java.util.Objects;

public class SecureChannelConnector {

    /**
     * Establishes a connection to a remote address using a SocketChannel
     * and handles the connection state changes securely.
     *
     * @param host The remote host name or IP address.
     * @param port The remote port.
     * @param timeoutMillis Connection timeout in milliseconds.
     * @return The connected SocketChannel in blocking mode.
     * @throws IOException If a connection or resolution error occurs.
     * @throws IllegalArgumentException If parameters are invalid.
     */
    public static SocketChannel connect(String host, int port, int timeoutMillis) throws IOException {
        Objects.requireNonNull(host, "Host cannot be null");
        if (port < 1 || port > 65535) {
            throw new IllegalArgumentException("Port must be between 1 and 65535");
        }
        if (timeoutMillis < 0) {
            throw new IllegalArgumentException("Timeout cannot be negative");
        }

        InetSocketAddress address = new InetSocketAddress(host, port);
        if (address.isUnresolved()) {
            throw new IOException("Could not resolve host: " + host);
        }

        SocketChannel socketChannel = SocketChannel.open();
        boolean success = false;
        try {
            socketChannel.configureBlocking(false);

            if (socketChannel.connect(address)) {
                success = true;
                socketChannel.configureBlocking(true);
                return socketChannel;
            }

            try (Selector selector = Selector.open()) {
                socketChannel.register(selector, SelectionKey.OP_CONNECT);

                long startTime = System.currentTimeMillis();
                long timeLeft = timeoutMillis;

                while (timeLeft > 0) {
                    int selected = selector.select(timeLeft);
                    if (selected > 0) {
                        Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
                        while (keys.hasNext()) {
                            SelectionKey key = keys.next();
                            keys.remove();

                            if (key.isConnectable()) {
                                SocketChannel channel = (SocketChannel) key.channel();
                                if (channel.finishConnect()) {
                                    success = true;
                                    channel.configureBlocking(true);
                                    return channel;
                                }
                            }
                        }
                    }
                    timeLeft = timeoutMillis - (System.currentTimeMillis() - startTime);
                }
            }

            throw new IOException("Connection timed out to " + address);
        } finally {
            if (!success) {
                try {
                    socketChannel.close();
                } catch (IOException e) {
                    // Suppressed to avoid masking the primary exception
                }
            }
        }
    }
}
